model_config.built_in_css:
/* ===== 全局基础 ===== */
* { box-sizing: border-box; }

body, .ry-wrap, .bet-wrap, .lq-wrap, .details-status pre, .actions .item {
  font-size: 16px !important;
  line-height: 2 !important;
}

.details-cot pre,
.details-scene pre,
.details-status pre,
.details-mem pre,
.actions .item,
.env,
.txt-you,
.txt-you-break,
.txt-shen,
.txt-lin {
  font-size: 16px !important;
  line-height: 2.2 !important;
  color: #d0c8e0 !important;
}

/* ===== 折叠面板统一间距 ===== */
.details-cot,
.details-scene,
.details-mem,
.details-player {
  margin-bottom: 8px !important;
  padding: 0 !important;
}

.details-cot summary,
.details-scene summary,
.details-mem summary,
.details-player summary {
  padding: 8px 14px !important;
  font-size: 15px !important;
  letter-spacing: 1.5px !important;
}

.details-cot pre,
.details-scene pre,
.details-mem pre,
.details-player pre {
  padding: 8px 14px !important;
  margin: 4px 0 !important;
  font-size: 15px !important;
  line-height: 1.9 !important;
}

.env {
  padding: 8px 0 !important;
  margin: 6px 0 10px 0 !important;
  font-size: 14px !important;
  color: #6a5a72 !important;
  text-align: center;
  letter-spacing: 1.5px !important;
  border-top: 1px solid rgba(200,88,88,0.08);
  border-bottom: 1px solid rgba(200,88,88,0.08);
}

.actions {
  padding: 14px 18px !important;
  margin: 10px 0 !important;
}

.actions .title {
  font-size: 16px !important;
  margin-bottom: 8px !important;
  padding-bottom: 6px !important;
  color: #c85858 !important;
}

.actions .item {
  padding: 6px 0 !important;
  font-size: 15px !important;
  line-height: 1.9 !important;
  color: #d0c8e0 !important;
}

.cut {
  margin: 14px 0 !important;
  border: none;
  height: 1px;
  background: linear-gradient(90deg,transparent,#1c1630,transparent);
}

/* ========================================================
   【角色独立状态栏】
   固定排列：玩家状态栏之后 · 记忆区之前
   ======================================================== */

/* ===== 🌷 林悠然独立状态栏 · 粉白 ===== */
.details-status-you {
  background: rgba(20, 14, 16, 0.92) !important;
  border: 2px solid rgba(240, 168, 168, 0.30) !important;
  border-radius: 10px !important;
  margin-bottom: 8px !important;
  padding: 2px !important;
  box-shadow: 0 2px 20px rgba(240,168,168,0.06) !important;
}

.details-status-you summary {
  color: #f0a8a8 !important;
  background: rgba(240, 168, 168, 0.08) !important;
  border-radius: 8px !important;
  padding: 10px 16px !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: 2px !important;
  cursor: pointer !important;
  user-select: none !important;
  border-bottom: 1px solid rgba(240, 168, 168, 0.12) !important;
}

.details-status-you summary:hover {
  background: rgba(240, 168, 168, 0.12) !important;
}

.details-status-you pre {
  background: rgba(0, 0, 0, 0.7) !important;
  color: #d0c8e0 !important;
  border-radius: 6px !important;
  padding: 10px 14px !important;
  font-size: 16px !important;
  line-height: 2.0 !important;
  margin: 6px 4px !important;
  border: 1px solid rgba(240, 168, 168, 0.08) !important;
  font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif !important;
  white-space: pre-wrap !important;
  word-wrap: break-word !important;
}

.details-status-you pre,
.details-status-you pre * {
  color: #d0c8e0 !important;
  font-size: 16px !important;
  font-weight: 400 !important;
}

